INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('eggerland-souzou-he-no-tabidachi', 41338, '1988-10-18', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co4wrk.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/schljs.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Eggerland: Souzou he no Tabidachi', 'Eggerland: Souzou he no Tabidachi is a part of the Eggerland series. The storyline isn''t really known since there is no storyline in the game. All you see is Lolo, the main character walk into a castle, and the doors shut behind him. There are 50 rounds in the game, which is less than the other Eggerland Famicom games. The game is unique out of all the other Eggerland titles for Famicom by allowing the player to create their own levels. Like the other Eggerland games, the objective of each stage is simple; collect all the heart frames and then collect the orb inside the treasure box to proceed to the next level. It won''t be easy though; King Egger has sent forth his enemies to take care of you. Lolo must use certain tactics to get by, such as trapping the enemies or knocking them off the screen temporarily.' FROM games WHERE igdb_id = 41338 ON CONFLICT (game_id, language_code) DO NOTHING;
