INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Nakajima Satoru: F-1 Hero', 'Superstar Nakajima Satoru (Michael Andretti in Western versions) personally guides you through the perilous and exciting world of Grand Prix Racing! Four of the most powerful racing machines are your to command on 16 famous international Grand Prix courses from around the globe! Hone your driving skills or challenge the best - it''s all up to you in this amazing simulation of Formula One racing!' FROM games WHERE igdb_id = 48302 ON CONFLICT (game_id, language_code) DO NOTHING;
