INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Aunt Arctic Adventure', 'Aunt Arctic Adventure plots you, Charlie the Chimp, and your friend Penguin Pete against Big Borus, the circus owner who has kidnapped your Aunt and forced her to work as a circus performer in the Arctic. In order to save your Aunt from this chilling, frightful scenario, you and your friend must negotiate 50 intricate, extensive levels of mentally challenging, surprise filled, action packed adventure. Along the way you will encounter hostile Eskimos, nasty penguins, and countless other types of diabolic creatures whose only interest is to stop you dead in your tracks before you can rescue your Aunt.' FROM games WHERE igdb_id = 14275 ON CONFLICT (game_id, language_code) DO NOTHING;
