INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('super-skateboardin', 12341, '1988-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/wu86skoqxeib2csp8utt.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Super Skateboardin''', 'Your Dad got you an after-school job at the factory where he works. You need the money ''cuz being the most radical boarder around means you''ve got heavy expenses.  The job is a skateboarder''s dream come true. Miles of halls and tubes to perfect your moves. Just cruise through and turn off all the machines and lights in the factory. Hurry up ''cuz power is leaking out fast!  Naturally, there''s a catch. You get paid depending on how much power you save. And you''ve got to be out of the factory by 5:15 pm today. One second more and you''ll never make the deadline for entering the Skateboarding Championship.' FROM games WHERE igdb_id = 12341 ON CONFLICT (game_id, language_code) DO NOTHING;
