INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The California Raisins', 'Three blues singing raisins are on a harrowing journey to escape the Raisin Factory. Battle through traditional 2D side scrolling platform puzzles to reach freedom, or face being baked in an oatmeal cookie.' FROM games WHERE igdb_id = 73306 ON CONFLICT (game_id, language_code) DO NOTHING;
