INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tetris', 'Tetris is the first Tetris game developed and released by Spectrum HoloByte, and the first version to be released commercially. There are two versions of the game; the revised version has the plane on the title screen removed (at the request of Elorg) and the military-themed backgrounds replaced (at the request of Pajitnov). The revised version was also featured on Tetris Gold.' FROM games WHERE igdb_id = 203099 ON CONFLICT (game_id, language_code) DO NOTHING;
