INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'If Monks Had Macs...', 'This is a collection of several stacks, with topics ranging from St. Thomas a Kempis’s Imitatio Christi, to a Christian anti-Nazi movement whose leaders were executed during World War II. Interspersed with all of this are games, including some pinball simulations and a role-playing spiritual adventure about a monk’s trek through the medieval wilderness to a monastic library.' FROM games WHERE igdb_id = 366833 ON CONFLICT (game_id, language_code) DO NOTHING;
