INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('takeshi-no-sengoku-fuuunko', 48887, '1988-11-25', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/zme25op36qq08nifvy42.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Takeshi no Sengoku Fuuunko', 'A Sengoku period board game simulation starring Beat Takeshi. Takeshi no Sengoku Fuuunko is a board game simulation starring Japanese comedian-turned-actor "Beat" Takeshi Kitano. Similar to the Game of Life, players move around a board earning money and occasionally encountering events such as a minigame - in which the player can increase their wealth should they succeed - or a penalty. The game has a Sengoku era theme running throughout, from its samurai characters to the tattooed gambler that rolls a dice for determining how many places a player can move around the board that turn. Beat Takeshi appears frequently while the game is being played dressed in traditional Sengoku era clothing. The game is presumably in reference to the TV show Takeshi''s Castle, which also starred Beat Takeshi and had a Sengoku era theme.' FROM games WHERE igdb_id = 48887 ON CONFLICT (game_id, language_code) DO NOTHING;
