INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Metropolis', 'Metropolis is a platformer with puzzle elements. Players navigate through screens, avoiding enemies to preserve energy. Collect items for later use, jump, and open doors. Control Moonboots the Lunar Explorer, stranded in Metropolis, on a mission to find and refuel his spaceship for a return to the moon. Moonboots can transform into companions with unique abilities by carrying specific objects. Access restricted areas and passages based on characters and objects.' FROM games WHERE igdb_id = 209520 ON CONFLICT (game_id, language_code) DO NOTHING;
