INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Skirmish', 'Skirmish, a BBC Micro and Electron game, adapts the classic Joust formula into a two-player experience where knights mounted on flying ostriches and storks battle against AI-controlled vulture riders. Players navigate platforms while using aerial combat tactics, striking opponents from above to turn them into eggs that must be destroyed before hatching into stronger foes. The game features three enemy types - Bounders, Hunters, and Shadow Lords - along with environmental hazards including crumbling platforms, lava trolls, and an invincible pterodactyl.' FROM games WHERE igdb_id = 381071 ON CONFLICT (game_id, language_code) DO NOTHING;
