INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('zak-mckracken-and-the-alien-mindbenders-enhanced', 2280, '1988-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co5vvr.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Zak McKracken and the Alien Mindbenders Enhanced', 'Zak McKracken and the Alien Mindbenders Enhanced is a modernized version of the classic 1988 point-and-click adventure game developed by Lucasfilm Games. This enhanced edition retains the original''s quirky humor and imaginative storyline while updating its visuals and gameplay for contemporary audiences. The game follows Zak McKracken, a tabloid journalist, as he uncovers a global alien conspiracy to reduce human intelligence. Players navigate Zak and his companions through various locations on Earth and beyond, solving puzzles and interacting with a cast of eccentric characters. The enhanced version likely features improved graphics, smoother animations, and potentially updated controls to make the game more accessible to modern players. While maintaining the charm and wit of the original, this version aims to introduce a new generation to the beloved adventure game, showcasing its innovative multi-character gameplay and blend of science fiction and comedy that made it a cult classic in the adventure game genre.' FROM games WHERE igdb_id = 2280 ON CONFLICT (game_id, language_code) DO NOTHING;
