INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Bases Loaded II: Second Season', 'Bases Loaded II: Second Season was released by Jaleco in 1988 as the second in the Bases Loaded series. It was only ever released for the Nintendo Entertainment System, and continued where Bases Loaded had finished as a successful baseball game on the NES console.' FROM games WHERE igdb_id = 10122 ON CONFLICT (game_id, language_code) DO NOTHING;
