INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Recordbreaker', 'Recordbreaker is a multi-event sports game for one or two players, where the player tries to achieve a world-record score in each of ten competitions. The events include: 100m sprint, 4x100m relay, Triple jump, Pole vault, Long horse, 100m swimming, Weightlifting, Horizontal bar, 100m hurdles and Shot put. The events can be played in any order, although losing an event results in the end of the game.' FROM games WHERE igdb_id = 111304 ON CONFLICT (game_id, language_code) DO NOTHING;
