INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('sylviana-ai-ippai-no-boukensha', 41249, '1988-08-10', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2mdl.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Sylviana: Ai Ippai no Boukensha', 'Sylviana lived with her mom in relative peace after her father passed away. One day, her mom came down with a mysterious illness. Despite everything Sylviana tried, her mother''s condition only got worse. Then one day, she heard a rumor about a Dr. Doppler, who can create a medicine that will cure any disease. She decides to head out and find this Dr. Doppler, and convince him to give her the medicine. However, she soon finds out that the doctor is unable to help her, due to having had his eight treasures stolen from him by demons. Sylviana vows to return the treasures to him in exchange for the medicine.' FROM games WHERE igdb_id = 41249 ON CONFLICT (game_id, language_code) DO NOTHING;
