INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Carrier Command', 'Carrier Command is a landmark 1980s computer game available on Amiga, Atari ST, PC, ZX Spectrum, Apple Macintosh, Commodore 64 and Amstrad CPC computers. Described by The Games Machine as a "seminal game destined to change the state of gaming", Carrier Command won accolades from across the industry.' FROM games WHERE igdb_id = 11992 ON CONFLICT (game_id, language_code) DO NOTHING;
