INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Captain Tsubasa', 'Captain Tsubasa is the first game based on Captain Tsubasa. It was released in 1988-04-28 by Tecmo for the Japanese market. This game is the first of the Tecmo game series. This videogame defined a unique concept: a sports RPG/Strategy and cinema action game. It follows the same story from the Captain Tsubasa (1983 TV series).' FROM games WHERE igdb_id = 213601 ON CONFLICT (game_id, language_code) DO NOTHING;
