INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Paris-Dakar Rally Special!', 'A NES game based on the famed Paris-Dakar Rally, developed by ISCO. While ostensibly a racing game, the style of gameplay tends to change per level. Paris-Dakar Rally Special! is an unusual racing game in which the player must successfully win the Paris-Dakar Rally. However, in order to do so, the player is faced with a wide variety of odd challenges to overcome, a scant number of which actually involve racing.' FROM games WHERE igdb_id = 48832 ON CONFLICT (game_id, language_code) DO NOTHING;
