INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Famicom Jump: Hero Retsuden', 'Famicom Jump: Hero Retsuden is a 1989 role-playing video game for the Family Computer published by Bandai. The game commemorates the 20th anniversary of Shueisha''s manga anthology Weekly Shōnen Jump. Set in a world that brings together many of the long-running titles that had appeared in the magazine, both of the past and present at the time of its release. The game consists of a main character wandering and encountering the many Jump heroes as they try to save the world from an alliance of many of the most powerful and evil of the Jump villains.' FROM games WHERE igdb_id = 48500 ON CONFLICT (game_id, language_code) DO NOTHING;
