INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('godzilla--4', 77247, '1988-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2vuo.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sc8dvc.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Godzilla', 'Godzilla is a 1988 action video game for the Commodore 16 and Commodore Plus/4 developed by Attila Cosir and distributed by Novotrade and then re-released by DELTASoft. It is a simple, endless game of avoiding taking hits from obstacles and enemies in a scrolling field. The first level introduces ground spikes, which can be jumped over. The second level introduces a UFO-like object that flies toward Godzilla''s head, which can be eaten. The third level introduces a giant bee that heads toward the back of Godzilla''s head, and is defeated by using fire breath. Finally, the fourth level introduces a space shuttle-like object that cruises on the ground, which can be jumped over.  Godzilla has 6 lives, and once they''re gone the player has to start over. The game awards points for keeping Godzilla alive, however it doesn''t keep track of high scores.  The game itself is completely silent, save for a brief voice sample when the game is started, and a loud, static-filled roar that Godzilla utters whenever he gets hit by an object.' FROM games WHERE igdb_id = 77247 ON CONFLICT (game_id, language_code) DO NOTHING;
