INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Vs. Tetris', 'Vs. Tetris is a game developed by Tengen for the Nintendo Vs. Unisystem arcade platform. The game would be the basis for Tetris (NES, Tengen) released some time later, and is noticeably less developed (e.g. the piece graphics use only solid colored or striped blocks).' FROM games WHERE igdb_id = 203108 ON CONFLICT (game_id, language_code) DO NOTHING;
