INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dragon Ball: Daimaou Fukkatsu', 'Dragon Ball: Daimaou Fukkatsu is a role playing video game released only in Japan by Bandai on August 12, 1988. It is the second Dragon Ball video game released for the Nintendo Famicom. Daimaō Fukkatsu is the first role playing game based on the Dragon Ball series. Its gameplay was reused in the Goku-den video game series. Daimaou Fukkatsu is also one of the games included in the game compilation J Legend Retsuden for Nintendo 3DS.' FROM games WHERE igdb_id = 72395 ON CONFLICT (game_id, language_code) DO NOTHING;
