INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tantei Jinguji Saburo: Yokohama-ko Renzoku Satsujin Jiken', 'The second game in the Tantei Jinguuji Saburo franchise. The top down RPG style investigation is removed in this game, making this a purely menu based adventure game. A murder happens in the port of Yokohama, as detective Jinguuji Saburo, you are tasked to investigate the twists and turns of the case to find the culprit.' FROM games WHERE igdb_id = 80147 ON CONFLICT (game_id, language_code) DO NOTHING;
