INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('bubble-bobble--9', 194439, '1988-07-02', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9eyy.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar3bh1.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Bubble Bobble', 'This is an enhanced port of the original version for the SEGA Master System/Mark III. The game now has 200 levels, new items like the peacock feather, blue book, and a blue crystal chalice have been added, and there are also 2 new mini-boss fights. The game also has hidden rooms which allows players to rack up bonus points and find items that are needed to see the best ending. The endings themselves have been changed to be a bit more cinematic. Super Bubble Bobble is a mode in the original version that happened after the player beat the original set of levels and had to beat them again with the enemies being swapped around. Beating this would allow the player to see the true ending. This version of the game lacks this mode as the 200 levels are considered one playthrough.' FROM games WHERE igdb_id = 194439 ON CONFLICT (game_id, language_code) DO NOTHING;
