INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'XZR: Hakai no Guuzou', 'An action RPG developed by Telenet Japan and released in 1988, it is the first part of the XZR/Exile trilogy. The game was controversial for its references to religion, politics, and drugs. Unlike its sequels, XZR was never released outside of Japan.' FROM games WHERE igdb_id = 70299 ON CONFLICT (game_id, language_code) DO NOTHING;
