INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('dragon-scroll-yomigaerishi-maryuu', 48512, '1988-01-04', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co6nuw.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sc7mua.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dragon Scroll: Yomigaerishi Maryuu', 'Dragon Scroll: Yomigaerishi Maryuu is an adventure game developed by Konami in 1987 for the Famicom. It is often compared to The Legend of Zelda in terms of game play, but it is considerably more difficult due to the lack of clues or information on how to proceed. The game is non-linear, and you must explore different territories in search of the eight stolen magical artifacts that maintain a sleep spell over a large and dangerous dragon. Enemies roam the overworld and dungeons, and must be defeated in order to earn experience points. Experience points are used to increase the player''s level, which makes him stronger and gives him access to stronger weapons and magic. Most useful items are well hidden and, even when obtained, are difficult to determine their appropriate use. The game features a password system which allows you to continue play where you left off.' FROM games WHERE igdb_id = 48512 ON CONFLICT (game_id, language_code) DO NOTHING;
