INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('jarinko-chie-bakudan-musume-no-shiawase-sagashi', 48453, '1988-08-15', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co744m.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Jarinko Chie: Bakudan Musume no Shiawase Sagashi', '"Jarinko Chie: Bakudan Musume no Shiawase Sagashi" is a graphical text-adventure game. It is a game based on the Jarinko Chie anime and manga about a dependable girl who struggles to help her troublesome father run a small tavern in Osaka. Unbeknownst to her dad, she occasionally visits her mother who left him not too long ago. She plans on trying to reunite them, but not until her father gets a job. Though it is largely text driven, there are moments where the player must play a mini-game in order to advance to the next chapter of the story.' FROM games WHERE igdb_id = 48453 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 48453 AND ge.slug = 'adventure' ON CONFLICT DO NOTHING;
INSERT INTO game_platforms (game_id, platform_id) SELECT g.id, p.id FROM games g, platforms p WHERE g.igdb_id = 48453 AND p.igdb_id = 99 ON CONFLICT DO NOTHING;
INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('akanbe-dragon', 71363, '1988-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co302s.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sc9j6f.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Akanbe Dragon', 'Akanbe Dragon can be seen as a forerunner to the company''s long-running Super Robot Taisen franchise. On a one-screen playfield, you have a group of dinosaurs opposing a computer-controlled group of beasts. As in chess, you move your creatures around the board, each creature having different movement patterns and range; some move only diagonally, others move only short distances in the cardinal directions. When two creatures end up on the same square, a fight commences. Unlike the Super Robot games, these fights are totally interactive action sequences seen from a side view. You must move your dragon to evade enemy fire and try to shoot down the opposition. Each creature has different stats such as speed, jumping height, strength and shot. Depending on the square the fight takes place on, the milieu changes, which can be both a hindrance and a boon for different units. Akanbe Dragon comes with a level editor for creating your own scenarios, and a continue option is also available if you lose the scenario.' FROM games WHERE igdb_id = 71363 ON CONFLICT (game_id, language_code) DO NOTHING;
