INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'King of Kings', 'A NES strategy game developed by Atlus and published by Namco. It was only released in Japan. The goal is to quickly conquer locations by producing a lot of units each turn and sending them against enemy forces. As with those games, there is also a little close-up graphic of the two units whenever they meet for battle, which shows how the two sides are faring in the conflict.' FROM games WHERE igdb_id = 48721 ON CONFLICT (game_id, language_code) DO NOTHING;
