INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('dokuganryu-masamune', 48525, '1988-05-05', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/afgxzwiwqcbxxdt8m4uh.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dokuganryu Masamune', 'Dokuganryu Masamune (独眼竜政宗?) is a historical simulation game developed and produced by Namco for the Famicom in 1988. It is the third such game to appear on the Famicom inside of a month, including Koei''s Nobunaga''s Ambition and HOT-B''s Takeda Shingen. This game is based on the life of Date Masamune, who held power in Japan during the early Edo period. An outstanding tactician, he was made all the more iconinc for his missing eye, and Date was often called dokuganryu (独眼竜? one-eyed dragon). In the game, you play as the warring overlord, and your aim is the unification of 11 regions under one rule. While comparable to other historical simulations released around the same time, this game is a little simpler and features immediate battle scenes, a hexagonal map, and includes mini-games such as a gold mine search and horseback archery. The game keeps a light, almost humorous tone, providing updates in the game via the Namcot newspaper, which shows changes in conversation tone and the emotions of your opponents. The difficulty of the game can be set, there are eight commands, and four types of battle forces. This game was only released in Japan, and has never been translated from the original Japanese.' FROM games WHERE igdb_id = 48525 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 48525 AND ge.slug = 'simulator' ON CONFLICT DO NOTHING;
