INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Simon', 'This is a version of the electronic game of the same name. The game creates a series of tones and lights and requires a user to repeat the sequence. If the user succeeds, the series becomes progressively longer and more complex.' FROM games WHERE igdb_id = 331044 ON CONFLICT (game_id, language_code) DO NOTHING;
