INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Eliminator', 'Eliminator is a classic horizontal shoot-em-up where the player flies his spaceship over a scrolling, alien landscape. As Group Commander of the United Earth Space Force, J.A. Davidson, the player is tasked to take his Skystrike Attack Craft to the vicinity of the Motare Nebulae and find out why several ships have vanished there without a trace. Killer Bubbles and Mutant crafts are encountered and should be eliminated.' FROM games WHERE igdb_id = 354648 ON CONFLICT (game_id, language_code) DO NOTHING;
