INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Kakefu-kun no Jump Tengoku Speed Jigoku', 'A video game released for the Nintendo Entertainment System in 1988 by Vic Tokai. The game''s main character is based on Kenji Sagara (相良 健治, Sagara Kenji), a popular Japanese child actor who was famous in the 1980s for his impersonation of baseball player Masayuki Kakefu.' FROM games WHERE igdb_id = 215129 ON CONFLICT (game_id, language_code) DO NOTHING;
