INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('hoshi-wo-sagashite-dot-dot-dot', 46149, '1988-05-02', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/hjnmjr4qckzizyiexv6i.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scbugj.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Hoshi wo Sagashite...', 'The game revolves around a dog and his family. Being one of the earliest adventure games for an 8-bit console system, the game tends to be simplistic compared to today''s adventure games. As a Japan exclusive video game, literacy is required in the Japanese language in order to play the game. The character seems to have an anime-like influence as the people are watching out for the dog that is sitting on a log. Among the human beings, however, is an alien-like creature. While the literal translation would be Searching the Stars..., the actual alternative title is The Story of Mio.' FROM games WHERE igdb_id = 46149 ON CONFLICT (game_id, language_code) DO NOTHING;
