INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Little Vampire', 'Little Vampire is an adventure-style visual novel (ADV) published in Japan by AliceSoft''s predecessor company, Champion Soft, in 1988. It is the direct sequel to Little Princess, and continues the adventures of Kurusu Miki and Ogawa Kentarou after their escape from Dracula''s Castle. The events of the game would later be retconned into the timeline of the Rance series, with Dracula developing into the Demon King Gi, and the game''s central antagonist, Ramon C. Burksham becoming one of the earliest-appearing Dark Lords.' FROM games WHERE igdb_id = 132718 ON CONFLICT (game_id, language_code) DO NOTHING;
