INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Federation 2: Community Edition', 'Federation 2, the space trading game, is a massively multi-player game set within an exciting world of interstellar commerce and intrigue, in which you interact and collaborate with lots of other players in real-time, and compete against them to climb the ranks. The aim of the game is to amass a larger fortune (in Imperial Groats) than any other player, and to climb the ranks by forging alliances and making friends with the right people. Cooperation is the name of the game in Federation.' FROM games WHERE igdb_id = 229756 ON CONFLICT (game_id, language_code) DO NOTHING;
