INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Death Mall 3000', 'A freeware game distributed in the late 80s via Macintosh''s HyperCard system. It is a point-and-click adventure game where, after spending time in cryostasis a lone astronaut crash lands on earth. Seeking shelter in an abandoned mall the player must find a way out and figure out what happened to the Earth.' FROM games WHERE igdb_id = 278028 ON CONFLICT (game_id, language_code) DO NOTHING;
