INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('ocean-ranger', 41134, '1988-04-21', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/at63xyynct0ua4ttytom.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ocean Ranger', 'A naval simulation game. The Ocean Ranger is the first of a new class of frigate sized foilborne missile ships. You are able to track and destroy targets on the sea surface, beneath the sea, and in the air. Missions occur in one of four locations (from easiest to most difficult), the Bering Sea, Southeast Asia, Central America, and the Persian Gulf. While in port you can choose to equip your ship with a variety of weapons, then take off to rid an area of hostile enemies. In battle the view is from the deck of the boat, allowing enemies to be targeted and destroyed.' FROM games WHERE igdb_id = 41134 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 41134 AND ge.slug = 'simulator' ON CONFLICT DO NOTHING;
