INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Necromancer', 'Necromancer, originally released as Jaseiken Necromancer is a fantasy role-playing video game. It was released first only in Japan for the PC Engine, but saw a later release for the Wii and Wii U Virtual Consoles, the latter being released worldwide. The Wii U release was when the game received its localized title, but the game itself is still only in Japanese.' FROM games WHERE igdb_id = 76450 ON CONFLICT (game_id, language_code) DO NOTHING;
