INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('captain-fizz-meets-the-blaster-trons', 14376, '1988-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co4o6c.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/hkhfcfzo2a33lrjadwj8.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Captain Fizz Meets the Blaster-Trons', 'The message is simple: co-operate or die! It''s double fun and double trouble all the way in Captain Fizz, the most exciting simultaneous two-player game you and a friend are ever likely to play. It''s a whole new world of split-screen, high-speed action, as both of you take on the nasty Blaster-Trons infesting the planet Icarus. Yup, it''s a tough mission all right, but you might just win out with the right blend of co-operation, courage, laser-hot reflexes, practical sense...and brains. The action is fast and furious in Captain Fizz, but if you can''t work out the right tactics you''ll both be dead meat. There are 22 levels of savage and relentless action to battle through before you reach your objective, the central computer that''s causing the evil infestation. You''ll never get there, though, unless you put your heads together and co-operate; your buddy can''t do it on his own, and neither can you. This is one program where even the easy games are hard. So remember- united you stand, but divided you fall.... Warning: this game is impossible to beat on you own.' FROM games WHERE igdb_id = 14376 ON CONFLICT (game_id, language_code) DO NOTHING;
