INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Battle of Olympus', 'The Battle For Olympus was developed by Infinity and Radical Entertainment for the Nintendo Entertainment System and Nintendo GameBoy. It was released in 1988, the year after Zelda II was released. The game borrowed many concepts from the popular Zelda game, utilizing various special weapons and tools as the game progresses.' FROM games WHERE igdb_id = 7773 ON CONFLICT (game_id, language_code) DO NOTHING;
