INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Maze Hunter 3-D', 'You are trapped in a twenty-level creature filled maze. Your job is to make your way to the bottom and get out alive. Pick up the iron bar and use it to destroy enemies that get in your way. Find the silver key to open the locked warp portal leading to the next level. Requires 3-D glasses to play.' FROM games WHERE igdb_id = 45674 ON CONFLICT (game_id, language_code) DO NOTHING;
