INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('where-in-europe-is-carmen-sandiego', 12824, '1988-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co4vfl.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sevl7ljdwfccbemjhgs6.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Where in Europe is Carmen Sandiego?', 'Where in Europe is Carmen Sandiego? is a multiplatform video game where players have to travel through Europe to collect the clue and the warrant necessary to capture Carmen Sandiego or one of her henchmen. The goal of this game is to track Carmen''s villains through the continent and arrest them and ultimately arrest Carmen herself. Production of the game was discontinued in 1990 due to the collapse of the Eastern Bloc of European countries, and the consequent major border and government changes that resulted.' FROM games WHERE igdb_id = 12824 ON CONFLICT (game_id, language_code) DO NOTHING;
