INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('crack', 94294, '1988-01-01', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co8y7d.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scu7bo.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Crack', 'Swiss developed Arkanoid style game, with a prehistoric theme. Play is for one or two players simultaneously (including a battle-mode), and options are available for mouse and joystick controls. A comprehensive level editor is also included. The players’ bat here is made out to look like a bone, and the ball is a spherical stone. Level backdrops are randomised pixel-painted scenes featuring different types of Dinosaurs. The bricks to knock out sometimes contain pickups to collect, such as a laser gun, an automatic CPU controlled bat navigation mode, extra life, slow-ball etc. A pickup is immediately activated upon collection, but subsequent ones collected are not if one is active, and clicking the right mouse button will cancel out the current effect for the last pickup collected. A bonus coconut game can be enabled from the main menu, which in turn lets you play this sub-game at predefined intervals during the course of standard play, where you control a caveman holding a pan, and the object is to catch coconuts that fall from trees with it, by moving from left to right on the single screen. Your bonus is tallied for how many coconuts you managed to catch in the allotted time.' FROM games WHERE igdb_id = 94294 ON CONFLICT (game_id, language_code) DO NOTHING;
