INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('super-real-baseball-88', 48395, '1988-08-30', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/ahfjuff8s6xnvchb2gfc.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Super Real Baseball ''88', 'Super Real Baseball ''88 is a baseball game developed by Pax Softonica for the Famicom and published in Japan by Vap in 1988. After Namco excited the market for baseball games with the release of Pro Yakyuu Family Stadium, many other companies attempted to meet the demand for more baseball games. This title differentiated itself from other baseball games by obtaining permission from the Professional Baseball Organization of Japan to use the official names of the 12 Japanese baseball teams and their players. This was a groundbreaking feature at the time. It was also the first game to depict an existing stadium with it''s actual name, the Tokyo Dome, which had just opened shortly before the game''s release. Outfielder and first baseman Warren Cromartie, formerly with the Montreal Expos, and playing for the Yomiuri Giants at the time, was chosen to help promote the game. To further distinguish the game, the developers chose to use a more realistic approach when depicting the players on the field, as opposed to the more cartoonish look utilized by Pro Yakyuu Family Stadium and many other baseball games. Additionally, the view remains fairly close to the ball after the batter hits the ball, as opposed to zooming out to a bird''s eye view of the field. Despite these changes, and efforts to promote the game, it was considered very difficult to play, as it employed rather complex controls for batting, pitching, and fielding that were not easy for many players to perform.' FROM games WHERE igdb_id = 48395 ON CONFLICT (game_id, language_code) DO NOTHING;
