INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('juushin-rogus', 234397, '1988-01-01', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co62ur.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scku2l.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Juushin Rogus', 'The space federation has assigned you a critical mission on planet Sagoth: defeat the forces of Geisel, a professor turned conqueror. Using lost technology found within Sagoth''s ruins, and supplies left across the planet, he''s created a robotic army superior to anything the federation can muster. You''re going alone, using a bipedal mech based on what little of Geisel''s research has been intercepted. It''s time to reclaim your lost bases, eliminate the scientist''s legions, and uncover the secrets lying beneath this world. Juushin ROGUS combines turn-based strategy, side-scrolling shooter action, and a light RPG layer into one accessible story. Managing and moving between your military bases, which automatically produce new units you can distribute, is crucial to success. Defending or attacking a base leads to action-platforming combat, where you jump, shoot, and fly across a battlefield full of limited replenishing enemies. As you destroy foes, your mech levels up over time, acquiring new weapons, aerial boosters, and even pilot bodyguards later on. To win, you must claim the final base and defeat Geisel in his lair—but it won''t be easy.' FROM games WHERE igdb_id = 234397 ON CONFLICT (game_id, language_code) DO NOTHING;
