INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('laydock-2-last-attack', 41682, '1988-12-19', NULL, NULL, NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Laydock 2: Last Attack', 'Sequel to the successful shoot ''m up Laydock. Again two jet fighters go on a joint mission, each space ship managed and controlled by a different player. The ships can be docked side-by-side or end-to-end for greater fire and fighting power. When docked one player is the pilot and the other is the weapons officer. But this game can also be played by a single player. When you progress in the game you can select more advance weapons systems to fight the over 50 different enemy characters. Compared with its predecessor there is not much changed only better graphics, more detailed backgrounds and inter level animations.' FROM games WHERE igdb_id = 41682 ON CONFLICT (game_id, language_code) DO NOTHING;
