INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Gold Medalist', 'Based on the Seoul Olympics, this is a multi-event track and field game for up to four players and featuring nine different events. Despite being heavily influenced by Konami''s own "Track and Field" series, Gold Medalist lacks both the addictiveness and tight gameplay mechanics of the games upon which it is based. The nine disciplines, which can be attempted in any order, are :  * 100 Metre Sprint  * Long Jump  * Horizontal Bars  * Freestyle Swimming  * Boxing  * Discus  * 110m Hurdles  * High Jump  * 400m Relay' FROM games WHERE igdb_id = 39920 ON CONFLICT (game_id, language_code) DO NOTHING;
