INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('hole', 79160, '1988-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co98ep.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scuym4.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Hole', 'Hole is a text adventure for the Dragon 32/64. The year is 2208, and the player is the sole crew member of a medium-range starship. Their mission is to visit a sector of space previously explored only by the starship Zelda. As the player enters the sector, they find themselves losing consiousness. The player now wakes up in some strange galaxy interlinked by a series of black holes. The player can travel to a series of different worlds useing their ship''s navigation system. Each system has unique environmental conditions that require wearing specific suits. There is a save and restore feature. All commands are via VERB NOUN entry.' FROM games WHERE igdb_id = 79160 ON CONFLICT (game_id, language_code) DO NOTHING;
