INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('stick-hunter-exciting-ice-hockey', 48618, '1988-01-18', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/kfwkbjqlm2y8d2kep2ek.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Stick Hunter: Exciting Ice Hockey', 'Stick Hunter: Exciting Ice Hockey is a game for the Famicom released only in Japan in 1987. It was never released in North America. Stick Hunter was the first actual ice hockey game created for a Nintendo gaming system. The game was designed so that 1 player could play against the computer, or 2 players could play simultaneously against each other. The length of the periods and difficulty level could both be adjusted. Playing as a character who has possession of the puck, the character could not only skate faster, but could only shoot the puck forward. So if the player wanted to pass to a teammate, the character on screen would have to be facing the person to which he''s passing. The same applied to shooting at the net and attempting to score a goal. The character would have to be facing the opposing net. A player without the puck could only skate faster. If the goalie had control of the puck, he could only pass to a teammate. As in the real-world sport of hockey, the object is to score more goals than the opposing team.' FROM games WHERE igdb_id = 48618 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 48618 AND ge.slug = 'sport' ON CONFLICT DO NOTHING;
INSERT INTO game_platforms (game_id, platform_id) SELECT g.id, p.id FROM games g, platforms p WHERE g.igdb_id = 48618 AND p.igdb_id = 99 ON CONFLICT DO NOTHING;
