INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('battle-valley', 11946, '1988-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/rsfp1lmgbl3y9voqfh7x.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sc80y3.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Battle Valley', 'This side-view shoot ''em up involves trying to retrieve two nuclear weapons which have been stolen by terrorists. These are located at opposite ends of the playing area, so you can pursue them in either order. Needless to say, the terrorists have plenty of forces out to prevent you getting too far.  Unusually, the game features both a helicopter and a tank - you choose either from the base, and can fly/drive back there to change. The best strategy is to use the helicopter to shoot out air-based enemies and repair the various bridges, then return for the tank. You get 4000 seconds in which to complete all this, and losing a life costs you 500 of these.' FROM games WHERE igdb_id = 11946 ON CONFLICT (game_id, language_code) DO NOTHING;
