INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('battlehawks-1942', 178, '1988-10-01', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co5vvt.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/md9ehylvtqf2j9xd728t.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Battlehawks 1942', 'Battlehawks 1942 is a groundbreaking World War II flight combat simulation game developed by Lucasfilm Games in 1988. Set in the Pacific Theater during the crucial year of 1942, the game allows players to experience aerial warfare from both American and Japanese perspectives. It focuses on three major naval battles: the Coral Sea, Midway, and the Eastern Solomons, offering a variety of historically accurate aircraft to pilot, including the American F4F Wildcat and SBD Dauntless, and the Japanese A6M Zero and D3A Val. The game stands out for its attention to historical detail and innovative graphics for its time. Players engage in diverse missions, from carrier defense to ship attacks and dogfights, with a unique damage model that visually represents the effects of combat on aircraft and vessels. Battlehawks 1942 successfully balances simulation elements with arcade-style action, making it accessible to a wide range of players while maintaining historical authenticity. Its multiple perspectives and varied missions provide significant replay value, cementing its status as a classic in the flight combat simulation genre and offering an engaging entry point to World War II air combat.' FROM games WHERE igdb_id = 178 ON CONFLICT (game_id, language_code) DO NOTHING;
