INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Famicom Grand Prix II: 3D Hot Rally', 'Famicom Grand Prix II: 3D Hot Rally is the sequel to Famicom Grand Prix: F-1 Race, although the two games are very different. In a departure from its predecessor, Famicom Grand Prix II features a behind-the-car view. Rather than consisting of a handful of short tracks, 3D Hot Rally provides three long tracks consisting of a variety of different terrain types giving the feel of an actual rally race. As the name implies, the game allows you to use the Famicom 3D System glasses to give the race a real feeling of depth.' FROM games WHERE igdb_id = 41256 ON CONFLICT (game_id, language_code) DO NOTHING;
