INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Arcus', 'Arcus is a RPG that is played entirely from first-person perspective. You navigate your hero by choosing a location from a menu. Once in dungeons, you have a separate menu whenever you encounter enemies. You fight them in turn-based combat, attacking physically or casting magic. The game is more close to Western RPG style than to Japanese one, and utilizes AD&D terminology for character stats.' FROM games WHERE igdb_id = 80836 ON CONFLICT (game_id, language_code) DO NOTHING;
