INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('aquanaut', 14168, '1988-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/wfozj4l8qoimmafayhtx.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Aquanaut', 'The Aquanaut team has been called in to investigate strange happenings around the Yendor Isles. And as the investigation continues, even stranger events come to light. Join Commander T.S. Williams and his team of top-notch Aquanauts in an assault on an underwater alien force who must be stopped! Too much is at stake to hesitate. In the Encounter at Shark Reef, you must fight through deadly jellyfish, swordfish, and sharks. Swimming through these waters is as dangerous as it can get, with every breath depleting your oxymix supply and every turn unveiling additional enemies. Then when you reach a fantastic alien craft, you''ve only got moments to plant the plasma bomb and get far enough away to escape injury when you detonate the explosive. In the Labyrinth, you will meet many blood-sucking waterbased aliens- each ready to send you to your maker! With careful blasting and clever strategic moves you just might get through it with some air in your lungs and your skin on your bones. But watch yourself in the underground city. One touch of a merman will fry your hide. Find the right devices and you might read into the story better. Tuck and roll around the merangels and splatter the hatchlings, grabbing weapons and information vital to your health- and the health of the captive population you realize you are there to set free. But not before the final battle with the master of the alien of the race. And he isn''t very nice.' FROM games WHERE igdb_id = 14168 ON CONFLICT (game_id, language_code) DO NOTHING;
