INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Jordan vs. Bird: One on One', 'Michael Jordan of the Chicago Bulls and Larry Bird of the Boston Celtics were the only two characters in the game, which allowed the player to participate in a one on one basketball game. Mini-games included a slam dunk contest (utilizing Jordan) and a three point contest (utilizing Bird).' FROM games WHERE igdb_id = 18837 ON CONFLICT (game_id, language_code) DO NOTHING;
