INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('capcom-bowling', 38535, '1988-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2ezr.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sc8hlv.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Capcom Bowling', 'Capcom Bowling is a top down bowling simulation released to arcades in 1988 by Capcom. Up to 4 four players could play a single game playing alternately. The controls feature a trackball which is used to control both direction and power, and two buttons which control left and right spin or hook. The game was released in both upright cabinet and latterly as a cocktail version. Most of the upright cabinet are conversion kits for existing cabinets although a limited number of dedicated cabinets were produced. These cabinets featured a birch plywood finish to mimic a bowling lane, a larger marbled trackball and painted side art. An alternate version, Coors Light Bowling, was released the following year.' FROM games WHERE igdb_id = 38535 ON CONFLICT (game_id, language_code) DO NOTHING;
