INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Kujaku-ou', 'Kujaku Ou the Peacock King, who is a young monk from Mt Koya with the direction of his Master, is sent to investigate strange paranormal incidents taking over Japan. In it the player takes the role of a band of heroes fighting against evil demons. The player interacts with the story by selecting actions from a list of options on screen (look, take, talk etc) and by a simple ''point-and-click interface.' FROM games WHERE igdb_id = 214836 ON CONFLICT (game_id, language_code) DO NOTHING;
