INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('angelus-akuma-no-fukuin', 130535, '1988-07-01', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co543s.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scqajf.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Angelus: Akuma no Fukuin', 'Akuma no Fukuin (Japanese for Devil''s Gospel) is a Japanese-style adventure game. The player chooses menu commands ("Look", "Talk", etc.) that are displayed under a still picture that represents the location. Most of these command have their own context-dependent sub-menus, i.e. it is possible (and sometimes necessary) to look at different things and talk about different topics. There are no puzzles, and the story usually advances when the player has triggered a necessary conversation or event. A business man in Peru and a girl visiting Japan both suddenly fall victim to a strange disease that turns the skin green and partially disfigures the face. The most unusual thing is that these two incidents occurred at the same time. Brian Pall, a journalist from the London Post, was on a flight to London when suddenly one of the passengers is struck with the same disease. These series of outbreaks have lead Brian and his partner, Eris Miler, to start their own investigation. Their discoveries eventually lead them going up against a mysterious religious group.' FROM games WHERE igdb_id = 130535 ON CONFLICT (game_id, language_code) DO NOTHING;
