INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', '20,000 Leagues Under the Sea', 'Based on the Jules Verne novel, this graphic adventure provides a first-person perspective on the realm of Captain Nemo and his enormous submarine craft, The Nautilus. Players guide three brave explorers -- marine biologist Pierre Aronnax, his assistant Conseil, and the rough-and-tumble seaman Ned Land -- who had boarded the warship Abraham Lincoln and embarked on a mission to hunt down an impossibly enormous "sea monster" reported by several merchant ships.' FROM games WHERE igdb_id = 2292 ON CONFLICT (game_id, language_code) DO NOTHING;
