INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Crazy Climber 2', 'Crazy Climber 2 (クレイジークライマー2?) is a 1988 arcade game developed and published by Nichibutsu. It is the sequel to the 1980 arcade game Crazy Climber. The gameplay is mostly identical to that of its predecessor, but there some significant differences. Unlike its predecessor, Crazy Climber 2 was only released in Japan.' FROM games WHERE igdb_id = 39808 ON CONFLICT (game_id, language_code) DO NOTHING;
