INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mines of Titan', 'A classic team based role playing game set on Titan, Saturn''s largest moon.  Mines of Titan is a remake, or update, of the Commodore 64 game Mars Saga. Mines of Titan is lengthier, with some new storylines, a few more creatures and a few details like colors are different. And of course the game''s location is moved from Mars to Titan. The cities and maps look the same.' FROM games WHERE igdb_id = 68301 ON CONFLICT (game_id, language_code) DO NOTHING;
