INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Saint Seiya: Ougon Densetsu - Kanketsu-hen', 'Saint Seiya: Ougon Densetsu - Kanketsu-hen is an RPG based on the anime and manga series Saint Seiya. It was developed and published by Bandai in 1988 for the Famicom as a sequel to the first Famicom Saint Seiya game, Saint Seiya: Ougon Densetsu. This version picks up where the first game left off, with the Bronze Saints about to take on all twelve of the Gold Saints in order to save Saori before time runs out. The game remains faithful to the original story, to the extent that your options are limited if you try to choose match-ups that didn''t occur in the show.' FROM games WHERE igdb_id = 48654 ON CONFLICT (game_id, language_code) DO NOTHING;
