INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Rally Bike', 'Rally Bike is a bird''s eye viewed motorcycle road racing game, where the player controls a motorcycle and must cross the finish line before an established number of competitor bikes. Fuel is a major obstacle, as running out of it results in game over. Any accident will cause great reduction of fuel, and stopping to refuel will cause competitor bikes to take advantage. Competitors never run out of fuel.' FROM games WHERE igdb_id = 39568 ON CONFLICT (game_id, language_code) DO NOTHING;
