INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Revolter', 'Tens of thousands of light years away, aliens are invading a second Earth. Save the planet in this vertical-scrolling shooter, now known more for its soundtrack; the first game ever to be scored by the legendary Hitoshi Sakimoto, and the third by equally-famous Masaharu Iwata.' FROM games WHERE igdb_id = 227761 ON CONFLICT (game_id, language_code) DO NOTHING;
