INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mormonoids From The Deep', '"Mormonoids From the Deep is a satirical adventure game loosely based on the writings of Hunter S. Thompson, H.P. Lovecraft, and the Book of Mormon. The object of the games is to destroy the evil Yogsoggsmith and escape from the town of Mormonville without sobering up. Armed only with a Colt .45, a Hertz rent-a-car, and your last six-pack, can you save the day and rescue "Unwholesome Olson"?' FROM games WHERE igdb_id = 246414 ON CONFLICT (game_id, language_code) DO NOTHING;
