INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Sengoku Mahjong', 'A Sengoku era themed Riichi (Japanese) Mahjong game. It was the first mahjong game released on the PC Engine and has since been rereleased on Wii Virtual Console and PSN. The game features Single mode and Conquest Mode. In single mode you play a single mahjong game against the game cast. In conquest mode you play as a prefecture and try to conquer the entirety of Japan by winning on Mahjong. The game only features 4-Player mahjong and can only be played against the computer. There is no password feature for the conquest mode, so it needs to be beaten in a single sitting.' FROM games WHERE igdb_id = 43202 ON CONFLICT (game_id, language_code) DO NOTHING;
