INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Steel Thunder', 'Lead an elite tank crew in one of four frontline U.S. tanks of the Cold War era, including the M60A3, M48A5 Patton, M3 Bradley CFV, and the devastating M1A1 Abrams. Assume the roles of Commander, Driver, and Gunner in an indomitable war machine that rolls out of the west like steel thunder.' FROM games WHERE igdb_id = 65568 ON CONFLICT (game_id, language_code) DO NOTHING;
