INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Rockman 2: Dr. Wily no Nazo', 'Rockman 2: Dr. Wily no Nazo is the original Japanese version of Mega Man 2. The Japanese version of the game doesn''t have difficulty settings, having its difficulty the same as the Difficult setting of the Western version, thus, being more difficult in comparison with the Normal mode of Mega Man 2.' FROM games WHERE igdb_id = 170742 ON CONFLICT (game_id, language_code) DO NOTHING;
