INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('hanjuku-hero', 78948, '1988-12-02', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/coa039.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scnau9.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Hanjuku Hero', 'The first game in the series, released in 1988 for Famicom. It was re-released on the Virtual Console in 2007 for the Wii, in 2013 for the Nintendo 3DS and in April 2014 for the Wii U. Hanjuku Hero is a real-time strategy RPG game. A king used the power of a mysterious egg to unify a continent. However, he suddenly died a day after the unification, and the countries subjected to his rule revolted. The king''s heir, the young prince must work with those few still loyal to the king and learn to use the power of the egg to bring order back to the continent. You have to journey throughout the continent with your allies to try and capture enemy castles. Upon reaching a castle, a battle will begin. Battles can also occur in the field. You have no control over these battles, as the stronger team usually prevails. Traditional RPG elements such as HP and money are present. The game has a humorous edge to it, featuring Japanese puns.' FROM games WHERE igdb_id = 78948 ON CONFLICT (game_id, language_code) DO NOTHING;
