INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('jack-nicklaus-greatest-18-holes-of-major-championship-golf', 18101, '1988-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co6o0d.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Jack Nicklaus'' Greatest 18 Holes of Major Championship Golf', 'Jack Nicklaus'' Greatest 18 Holes of Major Championship Golf is a golf-simulation video game developed by Sculptured Software, and published by Accolade in 1988. The game features simulations of eighteen holes from renowned golf courses in the United States, Scotland, and England: Four from Augusta National Golf Club, three from Pebble Beach Golf Links, three from the Old Course at St Andrews, two from the Riviera Country Club, two from Baltusrol Golf Club, one from Oakmont Country Club, one from Merion Golf Club, one from Muirfield, and one from Royal Lytham & St Annes Golf Club. In addition, the game contains simulations of two complete Nicklaus-designed 18-hole courses: The Castle Pines Golf Club and The Golf Club at Desert Mountain. It also bears the name and likeness of American professional golfer Jack Nicklaus. Less than two years before the game''s publication, Nicklaus won the final major golf championship of his career: the 1986 Masters Tournament. Augusta National Golf Club hosted the tournament. Players can compete against Nicklaus as a computer opponent, or any of eight other computer opponents of varying skill levels. Jack Nicklaus'' Greatest 18 Holes of Major Championship Golf was a commercial success for Jack Nicklaus Productions and Accolade. The two companies developed it into a video game franchise, and Accolade published numerous adaptations and sequels for more than ten years.' FROM games WHERE igdb_id = 18101 ON CONFLICT (game_id, language_code) DO NOTHING;
