INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('dance-of-the-vampires', 168323, '1988-12-31', NULL, NULL, 'https://images.igdb.com/igdb/image/upload/t_1080p/scd53q.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dance of the Vampires', 'With a jolt you wake, reaching from your subconscious mind for a pencil and a clean sheet of paper from the desk. Fumbling about with your fingers, however, you find not stationery, but the icicle-covered sleeve of uncle''s coast. Upon opening your eyes, the puzzle is solved. No longer are you in uncle''s study at Koenigsberg University, taking notes and generally keeping busy helping uncle. You are now heading up a narrow track that winds on through gradually deepening woods and snow, on another one of uncle''s “field trips”. This time researching a book on vampire bats and their connection with a strange race of humans. This is of course of little interest to you, being neither of a very adventurous nature or possession of a strange stomach. However, the strange wolf cries coming from the trees around you and the general air of expectancy does grip you in a frightening sort of way. Dance of the Vampires is an adventure game split into three chapters. The screen consist of the picture of the location that players are presently at, a description of that location, and a prompt where commands are entered. Recognizable commands include EXAMINE, TAKE, DRINK, ASK ABOUT, and directions can be abbreviated (ie: N, S, E, W, U, D).' FROM games WHERE igdb_id = 168323 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 168323 AND ge.slug = 'adventure' ON CONFLICT DO NOTHING;
