INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ultraman 2: Shutsugeki Katoku Tai', 'You are in charge of a Tokyo defense team of military experts who find ways of repelling kaiju. Find a way to hurt the monsters and deploy vehicles such as tanks and jets that are able to shoot them down before they destroy any critical buildings. When danger is near and all seems lost, call for Ultraman!' FROM games WHERE igdb_id = 41323 ON CONFLICT (game_id, language_code) DO NOTHING;
