INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('hopper-copper', 14117, '1988-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9p6r.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scwd4s.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Hopper Copper', 'The once quiet town of Grove Town now has a crime problem with four dangerous criminals running around the town committing crimes. This is a job for yourself as the local policeman but you have a problem, all the vehicles have been hidden by the criminals and all that is left is a Space Hopper to bounce around town and catch them all within a time limit. The game is viewed from the side as you move either left or right along the streets with the screen scrolling as you move. There are various street openings shown by a map of the street above the playing area. You are also able to see any criminals on the same street. At the bottom of the screen is a location of a crime and you can also see your location and a clock ticking down. You move about the streets in search of the criminals and if you find one then you bounce on top of him. Three of the four criminals are armed which are a club, tacks and a gun. Get hit by the gun and the tacks and you lose one of three lives. The club will just stun you and lose you valuable time.' FROM games WHERE igdb_id = 14117 ON CONFLICT (game_id, language_code) DO NOTHING;
