INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Donald''s Alphabet Chase', 'Donald''s Alphabet Chase (fully titled "Donald''s Alphabet Chase - Fun with Letters") is a 1988 educational video game developed by Westwood Associates and published by Disney Software. It was released on various home computers including the Amiga, Amstrad CPC, Apple II, Commodore 64, DOS and ZX Spectrum. An Atari ST version was planned by Nathan Software but got no release. The game was released in five different languages including English, Spanish, French, Italian and German.' FROM games WHERE igdb_id = 57631 ON CONFLICT (game_id, language_code) DO NOTHING;
