INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Powerstyx', 'Powerstyx is a Qix-style game where the player controls a dot that leaves an energy beam, gradually revealing a hidden picture. Monsters roam both revealed and unrevealed areas, causing the player to lose a life on contact or if the monsters cross an unfinished beam. Randomly appearing bonus symbols can grant various effects, such as extra lives, instant death, speed boosts, and more. Letters are also scattered across the levels, and spelling complete words is required to win. The standard objective is to reveal 75% of the screen to complete each of the 15 levels.' FROM games WHERE igdb_id = 123245 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_companies (game_id, company_id, role, is_primary) SELECT g.id, c.id, 'developer', false FROM games g, companies c WHERE g.igdb_id = 123245 AND c.slug = 'axxiom' ON CONFLICT DO NOTHING;
