INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Peter Beardsley''s International Football', 'Peter Beardsley''s International Football is a football video game developed in 1988 by Grandslam and endorsed by Peter Beardsley. Players select an international team to play as, and can choose to play against the computer in a one player league format, or two players in a two player league format. They can then select the other teams in each group.' FROM games WHERE igdb_id = 15339 ON CONFLICT (game_id, language_code) DO NOTHING;
