INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Master Blaster', 'You are the pilot of a Federation Clearance Ship and it''s your job to make sure the Space Lanes between Pluto and Mercury are clear from asteroids (reduced in size when shot), alien ships and shooting stars. You must clear three sectors for each planet in the Solar System before attempting to dock with the Factory Ship. The game is viewed from above your ship with the whole sector shown on screen. You can turn your ship left and right as well as thrust forward and you must shoot anything that moves on the screen. Once a sector is cleared you must enter a gate to move to the next one.' FROM games WHERE igdb_id = 268078 ON CONFLICT (game_id, language_code) DO NOTHING;
