INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Red Storm Rising', 'Red Storm Rising is a simulation video game based on Tom Clancy''s novel Red Storm Rising and released in 1988 by MicroProse. The player is put in charge of an American SSN submarine in the Norwegian Sea Theater with the overall role of a hunter killer performing various missions in the context of the global conflict described in the book representing a campaign. Its original Commodore 64 version was co-designed and co-programmed by the legendary game designer Sid Meier.' FROM games WHERE igdb_id = 15354 ON CONFLICT (game_id, language_code) DO NOTHING;
