INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Robbeary', 'Robbeary is an arcade adventure in which you help Bertie Bear rob a vast store. The store has 24 floors and each floor is bristling with guards. Bertie can climb ladders and jump from one floor to another but he must avoid being caught by the guards because capture means instant death. Bertie must collect all the fruit on each level before a key unlocking the door to the next floor is revealed. At some levels he may come across another key which opens a door where extra fruit can be collected.' FROM games WHERE igdb_id = 266675 ON CONFLICT (game_id, language_code) DO NOTHING;
