INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Cockpit', 'The Cockpit is a Simulation game, developed and published by Taito Corporation, which was released in Japan in 1988. Though the game is limited to simulating runway landings only. After a successful touchdown you can progress to other airports around the country, each with increasing difficulty in the way of wind interference. The graphics and controls are quite basic, but the game still aims to provide immersion during each short landing sequence. The later versions on X68000 and PC-98 feature control tower speech and higher resolutions which add further realism to the simulation.' FROM games WHERE igdb_id = 41755 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 41755 AND ge.slug = 'simulator' ON CONFLICT DO NOTHING;
