INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Fire Bam', 'Bam is a fifteen years old courageous boy. Like every boy his age, Bam must pass the village''s test and bring back an insect''s shell from the forest. But as he returns, and to his surprise, most of the village has been destroyed and his parents turned into demons. Armed with his sword, Bam sets forth in search of what happened to the village and his parents.' FROM games WHERE igdb_id = 41267 ON CONFLICT (game_id, language_code) DO NOTHING;
