INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Kaettekita Mario Bros.', 'Kaettekita Mario Bros. is an updated version of Mario Bros. that was released only in Japan. It had several new features including new levels and the option to save high scores. Excluding ports, this is the last Mario Famicom game. It was co-published by Nagatanien, a food company, and contains in-game advertising.' FROM games WHERE igdb_id = 67043 ON CONFLICT (game_id, language_code) DO NOTHING;
