INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Task Force', 'Negotiations have failed! So your anti-terrorist Task Force is the last hope for hostages held by deadly terrorists in a high-rise building. You have wire-guided missiles, but eh terrorists never miss when they shoot at you! You have to fire fast then they step into and open window. But look before you fire, they can shield themselves behind hostages.' FROM games WHERE igdb_id = 46890 ON CONFLICT (game_id, language_code) DO NOTHING;
