INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'John Madden Football', 'Old american football simulation co-designed by famous sportscaster John Madden. The first game in EA''s long-running Madden series. Different versions of this game have been available on almost every platform - with the Mega Drive version being the most famous of them all. The game concentrates more on tactics than pure action.' FROM games WHERE igdb_id = 4587 ON CONFLICT (game_id, language_code) DO NOTHING;
