INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Alpha-1', 'Alpha-1 is 2D side-scrolling slow-paced shoot''em up game in space, similar to R-Type. The player is pilot of Alpha-1 space craft, he fights against robotic-looking aliens'' invasion - aliens invade Earth, and action takes place in space and aliens'' lair. The player flies right forward and kill all enemies on screen. Alpha-1 has upgradeable energy cannon, ship can shoot down enemy missiles.' FROM games WHERE igdb_id = 14250 ON CONFLICT (game_id, language_code) DO NOTHING;
