INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('tatakae-ramen-man-sakuretsu-choujin-102-gei', 48390, '1988-08-10', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/lv7zwhifiofoseqiayat.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tatakae!! Ramen-Man: Sakuretsu Choujin 102 Gei', 'Tatakae!! Ramen-Man: Sakuretsu Choujin 102 Gei is an adventure game developed by Human Entertainment for the Famicom and published by Bandai in 1988. It is based off the Tatakae!! Ramenman series, which itself is a spin-off of the Kinnikuman series, known in the US as M.U.S.C.L.E.. Ramenman is a popular character in the Kinnikuman universe. The game follows the eponymous warrior Ramenman as he attempts to track down his father''s killers and bring them to justice with his many years of martial arts training. Notably, this game is the first true point-and-click adventure game for the system. While there had been many adventure games made for the NES, such as Portopia Renzoku Satsujin Jiken or Princess Tomato in the Salad Kingdom, they are largely driven by menus. Ramenman is directed by using the cursor to select an area to walk to or interact with instead much like classic Sierra adventure games such as King''s Quest.' FROM games WHERE igdb_id = 48390 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 48390 AND ge.slug = 'point-and-click' ON CONFLICT DO NOTHING;
