INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('shiryou-sensen-war-of-the-dead-part-2', 41737, '1988-02-01', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co505v.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sci9fl.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Shiryou Sensen: War of the Dead - Part 2', 'It''s set some years after the incident in the first game (where Lila managed to avert a portal into hell consuming the whole world), and terrorists have targeted the industrial city of Sun Dorado. This sequel has undergone radical changes from the original, with all of the RPG trappings stripped out. There''s no longer any kind of stats, menu system to navigate, day/night cycle, overworld map, or weapon recovery items. In fact the only items are drugs, which restore health to maximum and only one can be carried at a time, and key items with further the story. The biggest change is the combat: there are no longer any random battles. Taking place on a series of massively sprawling maps, as opposed to shrunken JRPG-style maps which warp you to new maps when entering buildings, all enemies can be seen immediately. Furthermore you never fight more than a single enemy at a time. If there''s something hostile in a new area, you can see his health bar at the bottom. In a lot of ways it closely resembles the original Metal Gear, except more sedate and with greater emphasis on NPC dialogue.' FROM games WHERE igdb_id = 41737 ON CONFLICT (game_id, language_code) DO NOTHING;
