INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dan Dare II: Mekon''s Revenge', 'Dan Dare II: Mekon''s Revenge is a fast-paced action game that pits the heroic Dan Dare against his nemesis, Mekon. Players infiltrate Mekon''s spaceship, racing against time to disable control boxes and thwart the villain''s plans. The game features genetically engineered SuperTreens as enemies, multiple levels to navigate, and a points system that rewards players with extra lives. With limited resources and the constant threat of Mekon and his Treen allies, players must strategically manage their energy and shields while progressing through increasingly challenging stages.' FROM games WHERE igdb_id = 13567 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 13567 AND ge.slug = 'shooter' ON CONFLICT DO NOTHING;
