INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('poseidon-wars-3-d', 46134, '1988-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co8flj.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scsxf0.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Poseidon Wars 3-D', 'Battle Stations! Battle Stations! Your country is being attacked. You''ll be fighting on the U.S.S. Poseidon; an armor-plated attack cruiser with radar, sonar, 76mm cannons and surface-to-surface missiles. First come the training rounds. They''ll throw everything they have at you... jets, cruisers, torpedoes, cannons. And then the fun really starts! Combat missions! You''re on the open seas. You have blips on the radar. Line up your gunsights and let ''em have it. You pick up an enemy cruiser on your sonar. Get ready with an armor piercing missile and send them to Davey Jones locker. If you complete your missions, you will be awarded with the Navy''s highest honor... a promotion to Fleet Admiral.' FROM games WHERE igdb_id = 46134 ON CONFLICT (game_id, language_code) DO NOTHING;
