INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Deja Vu 2: Lost in Las Vegas!!', 'This time you wake up in Las Vegas with great headache and realize that you are Ace Harding, who has to find $112,000 of recently murdered Chicago''s racketeer Joey Siegel for his boss and Las Vegas'' mobster Tony Malone. You have a choice to find money in one week or classical "or else". Just for formality you are watched by Malone''s thug Stogie Martin.' FROM games WHERE igdb_id = 12418 ON CONFLICT (game_id, language_code) DO NOTHING;
