INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('snatcher--1', 197937, '1988-11-26', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co4o2q.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scgohu.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Snatcher', 'Snatcher is a cyberpunk-themed graphic adventure game directed and written by Hideo Kojima and produced by Konami. The setting and story of Snatcher is heavily influenced by cyberpunk and science-fiction media, taking place in a large futuristic dystopian city. The story revolves around an investigator named Gillian Seed assigned to investigate a breed of bioroids known as "snatchers", who are killing humans and taking their place in society. The game is set in a primarily first person perspective and uses a menu-based interface that allows the protagonist to interact with his environment. The player can choose to "Look", "Investigate", "Talk", "Ask" and "Move" (in addition to other options) to acquire key items or receive vital information from other characters. The player can analyze items in Gillian''s belongings or show it to other characters. During key points of the game''s story, the player must pass shooting sequences to defend Gillian from assailants. These shooting segments use a 3x3 grid which the player can target to fire at enemies. A shooting trainer, called "Junker''s Eyes", is accessible at Junker HQ that allows the player to measure their accuracy.' FROM games WHERE igdb_id = 197937 ON CONFLICT (game_id, language_code) DO NOTHING;
