INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('arcade-game-construction-kit', 44125, '1988-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/iwp2idvc5dqvktwr1nxb.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Arcade Game Construction Kit', 'Arcade Game Construction Kit is a 1988 game creation system that allows users to design arcade-style games.[1] It was developed by Mike Livesay and published by Brøderbund for the Commodore 64. AGCK contained four floppy disks. The program features a joystick-driven menu system and a few pre-made games to play.  Included Games  AGCK TUTORIAL GAME -- This is a simple variation on classic arcade shooters such as Galaxian.  KANGARANG (designed by Gregory Hammond) -- You play as a kangaroo mother looking to rescue your baby and return to safety. Hazards include falling boulders, jumping fish, monkeys and natives.  ISLE QUEST (designed by Greg Johnson and Paul Reiche III) -- You play as a brave explorer in search of new lands and riches. Hazards include pirate ships, hostile natives.  MUSASHI (designed by Greg Johnson and Paul Reiche III) -- You play as an ancient samurai warrior looking to rescue his princess. You must fight your way through a fortress, collecting gold, sushi, and the mighty Sword of the Samurai.  GERG''S ADVENTURE (designed by Gregory Hammond) -- You play as Gerg, a tiny creature who wants to get back to his home. Gerg must pick up a variety of orbs to power up, and to clear each level.  SPACE WORRIES (designed by Paul Reiche III and Greg Johnson) -- You control a space ship, looking to collect mysterious metallic cylinders to destroy an enemy that has taken control of your planet.' FROM games WHERE igdb_id = 44125 ON CONFLICT (game_id, language_code) DO NOTHING;
