INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('microprose-pro-soccer', 94626, '1988-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co5027.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scu0m1.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Microprose Pro Soccer', 'This soccer simulation was programmed by "Sensible Software" (known through "Wizball" and "SEUCK") and published by "Microprose" (which until then had made a name for themselves with mostly warlike simulations). The game consists of two different soccer simulations, you can carry out a match in the stadium or indoors. The field is always shown from the top and scrolled softly into all directions. The player that is controlled at the moment can be recognized by a flickering football shirt. If you have the ball you can pass or shoot. The longer you keep the fire button pressed, the sharper the shot will be. Additionally, the trajectory bends if the joystick is pressed to the left or right. If the opponent has the ball, you can try to take it away from him with a sliding tackle. When the own keeper gets visible, you take over his controls and a press on the fire button makes the keeper jump. Indoor soccer has some fundemental changes to the rules. The ball cannot roll into the out, but it bounces from the cushion. Furthermore, the keeper can be the goalgetter himself (in contrast to the stadium where he is limited to the penalty area). If a goal is scored, the scene is repeated in slow motion and one can watch the attack unhurriedly. Extensive and clearly arranged menus enable you to change many parameters of "Microprose Soccer". These range from the length of a match (2 to 12 minutes) to details of the controls. Also the weather can be changed and by this you can get a proper rain shower during the game by coincidence. With a wet ground the ball rolls further and the players sometimes slip. Different game modes make for diversity. Up to 15 players can enter their names and then compete with each other in a league. One can also take part in a World Cup, whereby the venue corresponds to the one of a real World Cup. The computer takes over the controls of as many teams as needed. The strengths of the teams correspond approximately to the real national teams (random exceptions can happen). Scores can be saved any time and additionally there is a "Name Bank", a database with names of clubs, but there is limited memory, 16 clubs can be created. Therefore you cannot import the whole Premier League, but it is enough for an own league.' FROM games WHERE igdb_id = 94626 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_companies (game_id, company_id, role, is_primary) SELECT g.id, c.id, 'developer', false FROM games g, companies c WHERE g.igdb_id = 94626 AND c.slug = 'microprose-software-inc--1' ON CONFLICT DO NOTHING;
