INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Míhún Chē', 'Míhún Chē (迷魂車), more commonly known as BB Car (屁屁車) or eventually Ecstasy Car and Super Car (奇妙車) is a port of Rally-X and New Rally-X made for the Famicom by Hwang Shinwei in 1988. It was originally published by Chi Chi Toy Co., Ltd under the Mi Hun Che and Super Car title. BB Car is a slight update released 3 years later, in 1991.' FROM games WHERE igdb_id = 247447 ON CONFLICT (game_id, language_code) DO NOTHING;
