INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Exciting Soccer: Konami Cup', 'The true feeling of Arcade quality soccer is only achievable from Konami. Play a match with several selectable teams, and go against a friend!  A soccer game from Konami and part of their Exciting sports series for the Famicom Disk System.  Exciting Soccer is the fifth and final game in the Exciting sports series developed by Konami. It allows players to select (and rename, if they wish) a soccer team, each having their own set of strengths of weaknesses, and enter a tournament known as the Konami Cup.  Exciting Soccer uses a top-down perspective with both goals on the vertical axis. This would be a perspective popularized by later soccer games such as Kick Off and Sensible Soccer.  Pentarou the penguin makes a cameo during half-time shows.' FROM games WHERE igdb_id = 41236 ON CONFLICT (game_id, language_code) DO NOTHING;
