INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Konami 88', 'Konami ''88 (also known as ''88 Games or Hyper Sports Special) is the third in the Track & Field game series by Konami, where you test your Olympic skills against other world-class athletes. As the name implies, it is loosely based on (and not licensed by) the 1988 Summer Olympics in Seoul, South Korea. Bronze or silver medals are not good enough - you have to go for the gold to get to the next event. However, you must at least qualify in each event in order to compete in the next event:' FROM games WHERE igdb_id = 40228 ON CONFLICT (game_id, language_code) DO NOTHING;
