INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'A Question of Sport', 'This is the game of the long running BBC quiz show of the same name. Two teams of three battle against each other by answering sports questions. 2 Points are awarded for answering your question correctly. If you answer incorrectly the opposing team get a chance to answer it but for only 1 point. There are 6 rounds including picture board, what happened next and a quickfire buzzers round.' FROM games WHERE igdb_id = 8521 ON CONFLICT (game_id, language_code) DO NOTHING;
