INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Reikai Doushi', 'Reikai Doushi: Chinese Exorcist (Priest of the Spirit World: Chinese Exorcist), released outside Japan as Last Apostle Puppet Show, was an arcade fighting game released by Home Data in 1988. This was the first fighting game to use digitized sprites, motion capture animation, and claymation.' FROM games WHERE igdb_id = 40390 ON CONFLICT (game_id, language_code) DO NOTHING;
