INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Pachinko GP', 'A pachinko simulator for the Famicom Disk System. It was published by Data East in Japan only.  Pachinko GP (or Pachinko Grand Prix) is a Pachinko simulator from Data East for the Famicom Disk System. The goal is to play Pachinko in various machines found in Pachinko parlors across Japan, attempting to reach a Pachinko ball target (the total grows each time the player successfully fires a ball into a point-scoring zone) before a time limit expires before they move onto the next machine.' FROM games WHERE igdb_id = 41395 ON CONFLICT (game_id, language_code) DO NOTHING;
