INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Repton Infinity', 'Repton Infinity is as much a development tool as it is a game. Its predecessor Repton 3 included a level and graphics editor but Infinity takes it one step further with Reptol, a scripting language that allows the user to alter the behaviour of characters and objects. This means that the user can not only create new Repton levels but also completely new games. Four games are included to demonstrate the tools:  - Repton 3: Take 2  - Repton 4  - Robbo  - Trakker' FROM games WHERE igdb_id = 135408 ON CONFLICT (game_id, language_code) DO NOTHING;
