INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Cosmic Camouflage', 'The player controls a spaceship in order to avoid and destroy asteroids. The controls are rotate, thrust and fire. It expands on Meteors by introducing different types of asteroids and enemies, and a limited use camouflage function that allows the player to pass through asteroids and enemies.' FROM games WHERE igdb_id = 178134 ON CONFLICT (game_id, language_code) DO NOTHING;
