INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('deep-dungeon-iii-yuushi-he-no-tabi', 48514, '1988-05-13', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co7k9h.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Deep Dungeon III: Yuushi he no Tabi', 'Deep Dungeon III: Yūshi he no Tabi is the third installment in the Deep Dungeon series and the first to be released on the Famicom. This is the first Deep Dungeon title to offer the player a world to explore spanning multiple dungeons and multiple towns. It also allows the player to create their own party with up to three companions in addition to the hero character, with a choice of ranger, magician or priest for each character. Though the player can dismiss a character once the game has started, they will only be able to replace that character if they meet another pre-created playable character in one of the dungeons. However, the game will still end as soon as the protagonist "swordsman" character is defeated. This game retains the player-adjustable level-up stats from the first game, as well as the feature that removes randomized encounters if the player is at a significantly higher experience level than needed for their current location. One exclusive and rather annoying feature of this game engine is that sometimes the player character will fumble (remove) their equipped weapon, wasting that character''s turn. If the player wishes to re-arm their weapon, it will cost the player another turn. This is the only game in the series to award the player money (Gold) when defeating enemies. All other games will force the player to re-enter maps to collect respawning chests for money or items (for resale) if they want to gold farm.' FROM games WHERE igdb_id = 48514 ON CONFLICT (game_id, language_code) DO NOTHING;
