INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('rbi-baseball-2', 48090, '1988-01-22', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co6ouf.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sckdu5.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'R.B.I. Baseball 2', 'R.B.I. Baseball first set the standard as the only baseball game for play on the NES to use real players and their stats. R.B.I. Baseball 2 raises the standard to a new level: You get all 26 pro teams, each with a roster of 24 real players. Every player comes with his actual 1989 stats. There''s instant replay, as well as new and improved animation, graphics, music and sound effects to make the game come alive. As the manager, you get the designated-hitter rule, switch-hitting, and your own lineup of starters and subs. It''s so great, it''s approved by the Major League Baseball Players Association!' FROM games WHERE igdb_id = 48090 ON CONFLICT (game_id, language_code) DO NOTHING;
