INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'OutRun 3-D', 'Strap yourself in and take a 3-D ride on the wild side. Sega''s Out Run 3-D is so close to reality it will leave you breathless! As your car whips around treacherous curves and over hills, you can almost feel the engine screaming and the wind whipping through your hair!' FROM games WHERE igdb_id = 46136 ON CONFLICT (game_id, language_code) DO NOTHING;
