INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Legend of Blacksilver', 'In this turn based RPG, you play as a Farmer that one night dreams of a princess, an evil baron, and a mine full of a powerful but evil mineral called Blacksilver. The princess selects you to save the kingdom from the evil baron. You awake and begin your quest.' FROM games WHERE igdb_id = 61587 ON CONFLICT (game_id, language_code) DO NOTHING;
