INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Power at Sea', 'Power at Sea is a simulation of the Battle of Leyte Gulf, in which the Japanese attempt to capture the Pacific during World War II. The player commands a battleship, an aircraft carrier, and a troop ship, to launch naval gun barrages against enemy cave emplacements and direct assault forces to capture beachheads in enemy-held territory.' FROM games WHERE igdb_id = 55151 ON CONFLICT (game_id, language_code) DO NOTHING;
