INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Target Plus', 'Target Plus requires the Gun Stick accessory, a light gun. The game consists of two parts that can be played independently, all related to shooting ranges. In the first part, you will have to shoot flying plates, and in the second part of the game your goal will be to protect a cooked chicken from being relentlessly attacked by spiders or wasps.' FROM games WHERE igdb_id = 145867 ON CONFLICT (game_id, language_code) DO NOTHING;
