INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dragonia', 'Dragonia is an icon-driven RPG/adventure game with puzzles. Players control their character''s movements and actions through icons on the screen. They must find the Golden Crown within a time limit while facing challenges and assembling spells. As Cebrenia, an apprentice wizard, players aim to prove themselves to the Elder wizards in Dragonia.' FROM games WHERE igdb_id = 124242 ON CONFLICT (game_id, language_code) DO NOTHING;
