INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Bakutotsu Kijuutei', 'Bakutotsu Kijuutei, also known by its longer title as Bakutotsu Kijuutei: Baraduke II, is a scrolling shooter arcade game that was released by Namco in 1988 only in Japan. As in the original game, the players again take control of Takky (Player 1) and Hommy (Player 2) while fighting the strange-looking Octy and saving the one-eyed Paccets.' FROM games WHERE igdb_id = 40287 ON CONFLICT (game_id, language_code) DO NOTHING;
