INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Lipstick. ADV', 'In Lipstick. ADV the player takes the role of Gorou, a young Japanese private detective. One day, a wealthy and powerful old man contacts him and asks him to find a box which - according to him - contained a family treasure. The young detective thinks that fortune has finally smiled to him, but when his pretty girlfriend Otomi disappears, he realizes that the mystery is bigger than he thought...' FROM games WHERE igdb_id = 269686 ON CONFLICT (game_id, language_code) DO NOTHING;
