INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('sherlock-the-riddle-of-the-crown-jewels', 12623, '1988-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co5w31.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Sherlock: The Riddle of the Crown Jewels', 'Sherlock: The Riddle of the Crown Jewels is an interactive fiction computer game designed by Bob Bates and published by Infocom in 1987. Like most titles Infocom produced, the use of ZIL made it possible to release the game simultaneously for many popular computer platforms, including the Apple II, IBM PC, Atari ST, and Commodore 64. Sherlock is based on the legendary fictional detective Sherlock Holmes, created by Sir Arthur Conan Doyle. It is Infocom''s thirty-first game and is the first of two Infocom games developed by Challenge, Inc. using Infocom''s development tools. The year is 1887, and all of England is gearing up for the celebration of Queen Victoria''s Golden Jubilee, marking her 50th year as monarch. London, naturally, is especially frenzied. Reading the paper one morning, Sherlock Holmes seizes upon one seemingly unimportant notice: the Tower of London has been closed for "reasons of security." The great detective is unsurprised when, moments later, he is asked to investigate the theft of the Crown Jewels. The clues left behind, however, positively reek of a carefully laid trap; Sherlock decides that he must step aside and allow Dr. Watson to pursue the thief instead. But if the Jewels are not replaced within 48 hours, the British government will be forced to admit that their most prized possessions were stolen and suffer worldwide humiliation. The player fills the role of Watson, travelling around London in Hansom cabs while attempting to recover the Crown Jewels while encountering many characters from Doyle''s stories such as Mrs. Hudson, Mycroft Holmes, and Wiggins of the Baker Street Irregulars.' FROM games WHERE igdb_id = 12623 ON CONFLICT (game_id, language_code) DO NOTHING;
