INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Touhou Kenbun Roku', 'A sci-fi/comedy NES adventure game developed and published by Natsume in Japan only. Touhou Kenbun Roku ("The Travels of Marco Polo") is an adventure game that uses the then-ubiquitous NES adventure game system of having a series of menu commands with which to interact with the world. As a text-heavy Japanese adventure game, some fluency with the language is required in order to play it. The game depicts a troublemaker sent from the future back to 1275, when Marco Polo was in the midst of his explorations.' FROM games WHERE igdb_id = 48878 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 48878 AND ge.slug = 'adventure' ON CONFLICT DO NOTHING;
