INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Shapes and Patterns', 'Shapes and Patterns is a series of educational games for the Apple II. -Which is Different? - The player must select which of 4 shapes are different -Pattern Match - The player is shown a pattern of 4 shapes, and must be matched to an identical pattern -Memory Match - The player looks at a pattern, and then must match that pattern from a list of 4 patterns.' FROM games WHERE igdb_id = 285871 ON CONFLICT (game_id, language_code) DO NOTHING;
