INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Monopoly', 'Based on the popular board game from Parker Brothers about acquiring real estate and earning rent from players that land on their properties. The goal is to bankrupt all other players but a time limit can also be set with the winner being the person with the most money/assets when time expires. Up to 10 players can compete or computer opponents can be added on one of three difficulty settings.' FROM games WHERE igdb_id = 131548 ON CONFLICT (game_id, language_code) DO NOTHING;
