INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Meitantei Holmes: Kiri no London Satsujin Jiken', 'An adventure game starring Sir Arthur Conan Doyle''s Sherlock Holmes developed for the NES by Towa Chiki. Meitantei Holmes: Kiri no London Satsujin Jiken ("Great Detective Holmes: Fog of London Murder Case") is a murder mystery adventure game where the player directs Sherlock Holmes around London, finding clues and interrogating witnesses and suspects. Like its many NES adventure game contemporaries, it adheres to the Portopia formula of text adventure whodunits. It is the sequel to Towa Chiki''s earlier Sherlock Holmes game (Sherlock Holmes: Hakushaku Reijou Yuukai Jiken) and received a sequel (Meitantei Holmes: M-Kara no Chousenjou). None of these games were ever released outside of Japan.' FROM games WHERE igdb_id = 48778 ON CONFLICT (game_id, language_code) DO NOTHING;
