INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Raimais', 'Raimais is a maze chase arcade game released in April 1988 in Japan. The object of the game is to drive your vehicle around a maze in order to clear the maze of dots while avoiding the enemy. The game consists of 32 mazes total plus boss fights.' FROM games WHERE igdb_id = 98294 ON CONFLICT (game_id, language_code) DO NOTHING;
