INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('3d-stock-car-championship', 73294, '1988-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co6kcv.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scmqlo.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', '3D Stock Car Championship', 'This Super Sprint-inspired racing game uses a forced perspective viewpoint, with 4 small stock cars duking it out for anything between 1 and 99 laps. If you have an Interface II joystick adaptor, all 4 of these can be human controlled. The control method is unusual, in that the accelerator and the throttle are controlled in combination - releasing the throttle while at the current gear''s highest speed will move you up to the next one of the 8 gears. The brake turns into reverse when you reach zero velocity. The game has 24 circuits, and points are awarded 7-4-2-1 for each of these, with the championship going to the driver with the most points by the end. Before each race there is a 3-minute qualifying session, in which you lap continuously with the aim of getting the fastest lap.' FROM games WHERE igdb_id = 73294 ON CONFLICT (game_id, language_code) DO NOTHING;
