INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Drak', 'Your car has broken down in front of Count Dracula''s mansion, and since there is no help nearby, you decide to explore it. Drak is adventure game from ECP, with graphics in the form of Maniac Mansion. You move your character using the joystick and entering two-word commands with the keyboard. Some commands can be abbreviated, with two letter combinations of the noun and verb (eg: OP DO for OPEN DOOR). The object of this game is to escape the mysterious mansion before you are killed by Count Dracula''s assistant, Egor.' FROM games WHERE igdb_id = 168390 ON CONFLICT (game_id, language_code) DO NOTHING;
