INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Better Dead Than Alien!', 'Prepare to do battle as you and galactic hero Brad Zoom face the most revolting life forms ever to pollute the universe.  Watch with horror as sickening waves of malformed mutants threaten to obliterate freedom and democracy.  Risk your lunch as you and Brad choose between decency and annihilation.  It''s up to you. Better Dead Than Alien!' FROM games WHERE igdb_id = 11955 ON CONFLICT (game_id, language_code) DO NOTHING;
