INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('star-virgin', 41734, '1988-02-01', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/m7mspuzcbcxbddwwx9h7.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scd1xz.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Star Virgin', 'Star Virgins about as obscure as it comes, its a promotional hour long straight to video film from Japan. That was made to promote a little seen videogame of the same name distributed by Activision that only ever appeared on the long forgotten msx system. Plays out pretty much like a bonkers live action anime movie. Its a camp science fiction fantasy comedy about a girl whose secretly the lone fighter of justice Star Virgin, its her pursuit to stop the planet being attacked from robotic & puppet monsters, giant spiders and whatever else would warrant as being an end of level boss in an 80s video game... at least I think thats the overall idea, because its obviously never been translated into English its hard to totally fathom out what the hells going on, but hey thats the beauty of the Japanese movies right. Star Virgin herself is every Japanorama fanboys wetdream, shes a cute pink power ranger with her own spacecraft & powerbike and she kicks ass with a bazooka. The whole thing would have made an awesome music video for The Flaming Lips - Yoshimi Battles the Pink Robots (what I''m oddly playing while writing this). Sure its none essential throwaway stuff, but its a fun hour even without knowing what they''re saying. [Personal Reasons For Remembering] Really loved the spacecraft scenes complete with their robotic butler drivers and its not every day I get to see a movie featuring a robotic Statue of Liberty and an evil genius who lives on a floating volcanic island.' FROM games WHERE igdb_id = 41734 ON CONFLICT (game_id, language_code) DO NOTHING;
