INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Turbo Cup', 'Thrill to the excitement of Championship Sports Car racing! Drive at speeds in excess of 120 MPH!! Practice on each course first, before competing in a head to head race. Turbo Cup Challenge features accurate representations of four of the most exciting race tracks in Europe - MAGNY-COURS, DIJON-PRENOIS, NOGARO, and PAUL RICARD. You would never have believed that a computer could so accurately recreate all the excitement and danger of top class motor racing!!' FROM games WHERE igdb_id = 72328 ON CONFLICT (game_id, language_code) DO NOTHING;
