INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Assault Plus', 'This game is an upgrade of "Assault". Your mission is to reclaim your homeland by destroying the enemy forces that have taken over. You have an Assault tank, the supreme mobile weapon. Your tank has artillery guns and grenades, can perform Rapid Rolls to dodge enemy shots, and uses Power Wheelies to launch grenades.' FROM games WHERE igdb_id = 229464 ON CONFLICT (game_id, language_code) DO NOTHING;
