INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Masters of Kin', 'A sideways scrolling beat-em-up game. Evil roamed free in the lands. Zorg ''The Master of Kin'', took his wife to temple and before kissing her, suddenly the evil sorcerer Zangar came and invaded the place and took his wife kidnapped towards his castle. The knight Zorg begins his quest in the outlands of the Kin domain to rescue his wife from the enemy hands.' FROM games WHERE igdb_id = 40360 ON CONFLICT (game_id, language_code) DO NOTHING;
