INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Thunder Force II', 'A scrolling shooter and sequel to Thunder Force developed by Technosoft originally released for the X68000 computer before being ported to the Sega Mega Drive/Genesis game console. The Sharp X68000 version has an introduction sequence and an extra stage (top and side view) not found in the Sega Mega Drive/Genesis version.' FROM games WHERE igdb_id = 287461 ON CONFLICT (game_id, language_code) DO NOTHING;
