INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mountain Madness: Super Pro Skiing', 'An update of U.S. Ski Team Skiing, Mountain Madness: Super Pro Skiing includes code from that game, but offers new features such as enhanced graphics, create-your-own course, and random skiing, which has a helicopter dropping players off on uncharted mountains.' FROM games WHERE igdb_id = 5685 ON CONFLICT (game_id, language_code) DO NOTHING;
