INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Double Dare', 'Double Dare is the computer version of the game show originally hosted by Marc Summers. Like the TV show, the game is basically a trivia game with the added enhancement of being able to answer the question, or take a dare. Dares consist of the Toss-up Challenge, the Physical Challenge, and in the last round, the Obstacle Course. Questions are varied, and in large enough number to avoid excessive repetition even over several games worth of play.' FROM games WHERE igdb_id = 7998 ON CONFLICT (game_id, language_code) DO NOTHING;
