INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ace Attacker', 'Ace Attacker is a top-down volleyball game for one or two players. There are eight national teams available (Brazil, Cuba, France, Italy, Japan, Korea, Russia, USA) and matches are divided over six tiers, from an elimination match and three group matches to the semifinal and then the final. The difficulty level of the computer opponent increases in three steps from beginner through intermediate to expert.' FROM games WHERE igdb_id = 39901 ON CONFLICT (game_id, language_code) DO NOTHING;
