INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Return of the Dinosaurs', 'Return of the Dinosaurs is an educational game designed to teach kids about dinosaurs. The premise is that your hometown is suddenly overrun by dinosaurs, thanks to a malfunctioning time machine. You must find and return each dinosaur to its proper time period by learning about the dinosaurs using a database that comes with the game.' FROM games WHERE igdb_id = 147214 ON CONFLICT (game_id, language_code) DO NOTHING;
