INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Gang Busters', 'The evil Dagrus mob have just held up the bank on Main Street and got away with $1,000,000! With a sense of grim determination, officers Smith and Wesson set out to bring the dastardly gang to justice. Collect criminals while gunning down hundreds of others in this top-down shooter from Konami.' FROM games WHERE igdb_id = 39735 ON CONFLICT (game_id, language_code) DO NOTHING;
