INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('jetfighter-the-adventure', 50490, '1988-02-01', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/u4ldqoiuvwnude2mz4rf.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'JetFighter: The Adventure', 'Fly the F/A-18, F-16, and F-14 in a hypothetical invasion of the U.S. west coast by the Soviet Union. Missions range from combat air patrols to bombing runs to intercepting cruise missiles. Plus, carrier launches and landings are also possible.  Graphics include a detailed model of San Francisco -- the Golden Gate Bridge, Transamerica tower/pyramid, and more are all represented.  This game is effectively an enhanced version of F/A-18 Interceptor from the Amiga (same setting, programmers etc) with extra missions and the addition of the F-14.' FROM games WHERE igdb_id = 50490 ON CONFLICT (game_id, language_code) DO NOTHING;
