INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Nazoler Land Special!! Quiz-Ou wo Ikuse', 'A spin-off of Sunsoft''s Nazoler Land mini-game collections for the Famicom Disk System, this special version is a trivia game. Like the other Nazoler Land games, it was never released outside of Japan. Nazoler Land Special: Quiz-ou wo Ikuse (or "Search for the Quiz Masters") is a trivia game in which the player must answer trivia questions from eight different opponents across Japan in order to win the game. Because the game was never released outside of Japan, it needs a considerable amount of Japanese knowledge to play, both to understand the questions and to be able to answer them. It is not part of the core Nazoler Land series of games, which are all mini-game compilations.' FROM games WHERE igdb_id = 41397 ON CONFLICT (game_id, language_code) DO NOTHING;
