INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Superman', 'Superman is an arcade beat ''em up/shoot ''em up released by Taito in 1988. It is based on the character Superman by DC Comics. The player assumes the role of Superman, who must fight through five levels to make the world safe from the evil Emperor Zaas. The game can be played by up to two players simultaneously, with the second player taking control of a palette-swapped version of Superman.' FROM games WHERE igdb_id = 131546 ON CONFLICT (game_id, language_code) DO NOTHING;
