INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Super Black Onyx', 'Super Black Onyx is an RPG developed by Bullet Proof Software for the Famicom and published in Japan in 1988. It is an expanded version of the game The Black Onyx, which includes the ability to cast spells, more monsters, and a larger dungeon to explore. It also enhances the presentation of the graphics beyond what was standard for the computer versions at the time, and simplified the controls to be played with a control pad.' FROM games WHERE igdb_id = 48704 ON CONFLICT (game_id, language_code) DO NOTHING;
