INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ale Hop!', 'Mix between arcade and platform game with horizontal scroll, where your mission is to guide a ball along several circuits, collecting items that increase the score or bring us some benefits, such as speed, long jumps, etc.. There is a time limit to complete each circuit, so jumping accuracy is key to advance in the game.' FROM games WHERE igdb_id = 92777 ON CONFLICT (game_id, language_code) DO NOTHING;
