INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('bmx-ninja', 13413, '1988-05-14', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/x5po7ljuohpm91smngsz.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'BMX Ninja', 'After a hard days training with the freestyle team at the local dirt track, Phil "Pookie" Wheeler, unofficial BMX Ninja, whilst travelling home on his bike, a Blackfoot Falcon, was set upon by a rival team, the Diamond Backs, whose leader is intent on gaining the ultimate street cred. Your title. You must prove to yourself and your girlfriend that you are capable of keeping your title. Should you fail in your task, you will not only lose your title, you will lose your girlfriend (who wants to be seen with a loser anyway?) and your dignity. Should you succeed, you will be rewarded by your girlfriend. Should you complete a certain number of areas, you will receive the ultimate reward from her. (We''re not telling you what it is, so find out yourself if you can.)' FROM games WHERE igdb_id = 13413 ON CONFLICT (game_id, language_code) DO NOTHING;
