INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Syvalion', 'Syvalion is an arcade shooter video game released by Taito in 1988 and designed by Fukio Mitsuji, creator of Bubble Bobble. The player controls a golden metal dragon which flies around, breathing fire at its enemies while collecting power-ups to recharge its fire. The enemies are robots and tanks. At the end of each level, the player fights a boss.' FROM games WHERE igdb_id = 40249 ON CONFLICT (game_id, language_code) DO NOTHING;
