INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mirai Ninja', 'Mirai Ninja, is a side scrolling beat ''em up arcade video game, released by Namco in 1988 exclusively in Japan. Mirai Ninja was adapted into the Japanese live-action film of the same name, which was also produced by Namco. The game runs on Namco System 2 hardware, and is the first Namco game to be adapted into a film.' FROM games WHERE igdb_id = 38548 ON CONFLICT (game_id, language_code) DO NOTHING;
