INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('psy-o-blade', 28023, '1988-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9a86.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scv2uo.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Psy-O-Blade', 'In 21th century, there are three main powers on the Earth. The free world and the communist block carried over from the 20th century; the third power is the New Communist Federation. Since a program of denuclearizing was supported by all those powers, the New Communist Federation developed a devastating non-nuclear weapon: the satellite "Raiden". The two other powers competed with the New Communist Federation, developing their own killer satellites, and the danger of total annihilation became once again an issue. Seeing no future for the Earth, humans started to colonize other planets. In 22th century, they sent an experimental ship "Septemius 1" to a star six light years far away from the Solar System. The ship''s main computer, "Racoon", sent a strange message before stopping any communication. Keith McDonnell, a seventeen-year-old crew member of the ship "Septemius 2", was sent to investigate the strange disappearance. Psy-O-Blade is a Japanese adventure in anime style. The player interacts with the game world by moving a cursor and clicking on objects to examine or use them, and people to talk to them, or by choosing options ("Move" and "Scroll") from a menu. There are no puzzles to solve; the player advances in the game by talking to characters, visiting different locations, as well as examining and using objects.' FROM games WHERE igdb_id = 28023 ON CONFLICT (game_id, language_code) DO NOTHING;
