INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Princess Tomato in the Salad Kingdom', 'Valiant Sir Cucumber must rescue Princess Tomato from evil Minister Pumpkin in this offbeat adventure game for NES. Static scenes are viewed from a first-person perspective inside a window, with a description of the area appearing underneath. Actions such as "move," "talk," "give," and "fight" are initiated by selecting individual buttons positioned along the view window''s edges. You''ll interact with an assortment of personified fruits and vegetables throughout your travels across Salad Kingdom, all while acquiring various items to solve puzzles. Pursue Tomato''s captors across nine locales to restore peace to the land.' FROM games WHERE igdb_id = 48221 ON CONFLICT (game_id, language_code) DO NOTHING;
