INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('european-champions', 79743, '1988-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co8io7.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scftjh.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'European Champions', 'European Champions is an immersive football management simulation focused on international European competitions. Players step into the role of a national team manager, guiding their chosen country through qualification rounds and into the European Championships. The game offers a comprehensive management experience, encompassing squad selection, tactical decisions, and strategic gameplay choices. Matches are presented through a top-down view with text descriptions of key events, allowing players to follow the action and make real-time decisions. With features like friendly matches, adjustable game speed, and detailed management options including medical staff oversight, European Champions delivers an engaging and in-depth football management experience centered on the thrills of international tournaments.' FROM games WHERE igdb_id = 79743 ON CONFLICT (game_id, language_code) DO NOTHING;
