INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Excalibur', 'Excalibur is 2D arcade side scrolling shoot''em up game. The game hasn''t real story and has quite a simple game play - the player controls a red space ship, flies straightforward, avoid obstacles and shoot enemies in various locations (mostly mountains with space background). The enemies are in many types, shapes and colours - spaceships, "molecules", geometric figures, etc. If a spaceship flies too slowly, then it has a tendency to fall down.' FROM games WHERE igdb_id = 143254 ON CONFLICT (game_id, language_code) DO NOTHING;
