INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('kyuukyoku-harikiri-stadium-88-senshuu-shin-data', 48311, '1988-12-16', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/fnwq1vbfjg8kji3tires.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Kyuukyoku Harikiri Stadium ''88 Senshuu Shin Data', 'Kyuukyoku Harikiri Stadium ''88 Senshuu Shin Data (Ultimate Harikiri Stadium ''88 Players Updated Data Version) is a baseball game developed by Taito Corporation for the Famicom and NES. It is an updated version of Taito''s original Kyuukyoku Harikiri Stadium. Like its predecessor, it is a straightforward baseball simulation game for the Famicom which was never released outside of Japan. Besides a roster update and a few graphical improvements there is little difference between this and the previous game in the series. This process of having minor incremental improvements between annual releases would eventually become common practice in console sports games.' FROM games WHERE igdb_id = 48311 ON CONFLICT (game_id, language_code) DO NOTHING;
