INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('gold-rush', 12121, '1988-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co5v57.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/v7y4epaq92ddsnaumylm.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Gold Rush!', 'Gold Rush! takes you back to the year 1849, when gold was discovered in California. It was certainly one of the most exciting times in American history. Gold Rush! includes the three routes tens of thousands took to the gold regions. Become Jerrod Wilson and experience each trek as you travel from New York to California. Whichever route you decide to take, you will see many historical sights. Try going overland across the Great Plains and huge mountain ranges, crossing the Isthmus of Panama, or rounding Cape Horn on the tip of South America. If you survive and arrive at Sutter’s Fort, the adventure is still only half over! Many other puzzles remain to be solved before you achieve your goals in California.' FROM games WHERE igdb_id = 12121 ON CONFLICT (game_id, language_code) DO NOTHING;
