INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('19-part-one-boot-camp', 41010, '1988-10-07', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co93xe.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', '19 Part One: Boot Camp', '19 Part One: Boot Camp is a visceral simulation that immerses players in the experience of a young American draftee during the escalation of the Vietnam War in 1965. The game begins by contrasting the comfortable civilian life of a 19-year-old with the jarring reality of conscription. Players are thrust into the grueling world of basic training, where they must navigate the physical and psychological challenges of military preparation. Through a series of intense exercises, the game tests the player''s coordination, stamina, and morale, offering a realistic portrayal of the transformation from civilian to soldier. Boot Camp serves as a powerful introduction to the broader Vietnam War experience, setting the stage for the dramatic personal and historical events to follow.' FROM games WHERE igdb_id = 41010 ON CONFLICT (game_id, language_code) DO NOTHING;
