INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Armorik the Viking: The Eight Conquests', 'Action platformer with incredibly harsh time limits and infinitely respawning enemies.  You are brave warrior Armorik, seeking to immortalize your name in the book of Viking legends. Luckily for you, the great god Thor has reviewed your application and mulled over your case. Thor agrees to reward you with eternal fame... provided that you single-handedly conquer the eight territories of the North.' FROM games WHERE igdb_id = 69172 ON CONFLICT (game_id, language_code) DO NOTHING;
